// pricing.service.ts
export class PricingService {
  calculateOrderTotal(order: Order): number {
    let total = 0;
    for (const item of order.getItems()) {
      const price = item.getProduct().getBasePrice();
      const qty = item.getQuantity();
      total += price * qty;
    }
    // Apply customer discount
    const tier = order.getCustomer().getMembership().getTier();
    const discount = tier === 'gold' ? 0.15 : tier === 'silver' ? 0.10 : 0;
    total = total * (1 - discount);
    // Apply promo
    if (order.getPromoCode()) {
      const promo = order.getPromoCode().getDiscount();
      total = total * (1 - promo);
    }
    return Math.round(total * 100) / 100;
  }

  formatOrderSummary(order: Order): string {
    const customer = order.getCustomer();
    const address = customer.getAddress();
    return [
      `Order #${order.getId()}`,
      `Customer: ${customer.getFirstName()} ${customer.getLastName()}`,
      `Ship to: ${address.getStreet()}, ${address.getCity()}, ${address.getState()} ${address.getZip()}`,
      `Total: $${this.calculateOrderTotal(order)}`,
    ].join('\n');
  }
}

